import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFileSync, mkdtempSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { spawn } from 'node:child_process';
const [root, scenarioFile] = process.argv.slice(2);
const scenario = readFileSync(scenarioFile, 'utf8');
const app = readFileSync(join(root,'src/graph-view/app.js'),'utf8').split('await refreshRuns();\nlet tick = 0;')[0];
let resolve, reject; const result = new Promise((a,b)=>{resolve=a;reject=b;});
const requests=[];
const server=createServer((req,res)=>{
  if(req.method==='POST'&&req.url==='/r10-result'){
    let body='';req.setEncoding('utf8');req.on('data',s=>body+=s);req.on('end',()=>{res.writeHead(204).end();resolve(JSON.parse(body));});return;
  }
  const name=req.url?.split('?')[0].slice(1)||'index.html';
  requests.push(name);
  if(!['index.html','app.js','layout.js','usage-pages.js','task-scope.js','style.css'].includes(name)){res.writeHead(404).end();return;}
  res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html');
  res.setHeader('Cache-Control','no-store');
  if(name==='app.js')res.end(app+`\nconst nativeFetch=globalThis.fetch.bind(globalThis);\ntry {\n${scenario}\n} catch(error) { await nativeFetch('/r10-result',{method:'POST',body:JSON.stringify({error:String(error.stack)})}); }`);
  else res.end(readFileSync(join(root,'src/graph-view',name)));
});
await new Promise(r=>server.listen(0,'127.0.0.1',r));
const profile=mkdtempSync('/tmp/r10-async-chrome.');mkdirSync(join(profile,'home'));
const browser=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',[
  '--headless','--no-sandbox','--enable-automation','--no-default-browser-check','--disable-component-update','--disable-default-apps','--no-service-autorun','--password-store=basic','--use-mock-keychain','--disable-gpu','--disable-background-networking','--no-proxy-server','--disable-background-timer-throttling','--disable-renderer-backgrounding','--no-first-run',`--user-data-dir=${profile}`,`http://127.0.0.1:${server.address().port}/`
],{env:{...process.env,HOME:join(profile,'home')},stdio:['ignore','ignore','pipe'],detached:true});
browser.stderr.on('data',()=>{});browser.on('error',reject);
const deadline=setTimeout(()=>reject(Error('r10 fixture did not report in 25s')),25000);
try { const observed=await result;assert.ok(!observed.error,observed.error);console.log(JSON.stringify(observed,null,2)); }
finally {
  clearTimeout(deadline);
  try{process.kill(-browser.pid,'SIGKILL');}catch(e){if(e.code!=='ESRCH')throw e;}
  browser.stderr.destroy();browser.unref();server.closeAllConnections();await new Promise(r=>server.close(r));
  rmSync(profile,{recursive:true,force:true,maxRetries:3,retryDelay:100});
}

